import test from 'node:test';
import assert from 'node:assert/strict';
import { roundCents, formatEuros, parseEuros, RATES, convert, formatMoney } from '../src/money.js';

test('roundCents banker\'s rounding half to even', () => {
  assert.equal(roundCents(124.5), 124);
  assert.equal(roundCents(125.5), 126);
  assert.equal(roundCents(2.4), 2);
  assert.equal(roundCents(-0.5), 0);
});

test('formatEuros basic amount', () => {
  assert.equal(formatEuros(123456), '€1,234.56');
});

test('formatEuros negative amount', () => {
  assert.equal(formatEuros(-5), '-€0.05');
});

test('parseEuros basic amount', () => {
  const result = parseEuros('12');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1200);
});

test('RATES has correct values', () => {
  assert.equal(RATES.EUR, 1);
  assert.equal(RATES.USD, 1.085);
  assert.equal(RATES.GBP, 0.8425);
});

test('convert EUR to EUR returns same amount', () => {
  const result = convert(10000, 'EUR');
  assert.equal(result.ok, true);
  assert.equal(result.value, 10000);
});

test('convert EUR to USD', () => {
  const result = convert(10000, 'USD');
  assert.equal(result.ok, true);
  // 10000 EUR cents = 100 EUR
  // 100 EUR * 1.085 USD/EUR = 108.5 USD = 10850 USD cents
  assert.equal(result.value, 10850);
});

test('convert EUR to GBP', () => {
  const result = convert(10000, 'GBP');
  assert.equal(result.ok, true);
  // 10000 EUR cents = 100 EUR
  // 100 EUR * 0.8425 GBP/EUR = 84.25 GBP = 8425 GBP cents
  assert.equal(result.value, 8425);
});

test('convert with small amount to USD', () => {
  const result = convert(100, 'USD');
  assert.equal(result.ok, true);
  // 100 EUR cents = 1 EUR
  // 1 EUR * 1.085 USD/EUR = 1.085 USD = 108.5 USD cents -> rounds to 109
  assert.equal(result.value, 109);
});

test('convert with small amount to GBP', () => {
  const result = convert(100, 'GBP');
  assert.equal(result.ok, true);
  // 100 EUR cents = 1 EUR
  // 1 EUR * 0.8425 GBP/EUR = 0.8425 GBP = 84.25 GBP cents -> rounds to 84
  assert.equal(result.value, 84);
});

test('convert unknown currency returns UNKNOWN_CURRENCY', () => {
  const result = convert(10000, 'JPY');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'UNKNOWN_CURRENCY');
});

test('convert with negative amount EUR to USD', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, -10850);
});

test('convert with zero amount', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('formatMoney EUR format', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney USD format', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney GBP format', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney negative EUR', () => {
  assert.equal(formatMoney(-5, 'EUR'), '-€0.05');
});

test('formatMoney negative USD', () => {
  assert.equal(formatMoney(-5, 'USD'), '-$0.05');
});

test('formatMoney negative GBP', () => {
  assert.equal(formatMoney(-5, 'GBP'), '-£0.05');
});

test('formatMoney zero amount', () => {
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
});

test('formatMoney single digit cents', () => {
  assert.equal(formatMoney(105, 'EUR'), '€1.05');
  assert.equal(formatMoney(105, 'USD'), '$1.05');
  assert.equal(formatMoney(105, 'GBP'), '£1.05');
});

test('formatMoney with thousands separator EUR', () => {
  assert.equal(formatMoney(1234567, 'EUR'), '€12,345.67');
});

test('formatMoney with thousands separator USD', () => {
  assert.equal(formatMoney(1234567, 'USD'), '$12,345.67');
});

test('formatMoney with thousands separator GBP', () => {
  assert.equal(formatMoney(1234567, 'GBP'), '£12,345.67');
});

test('convert and format round-trip EUR to USD and back', () => {
  const eurCents = 50000;
  const usdResult = convert(eurCents, 'USD');
  assert.equal(usdResult.ok, true);

  const formatted = formatMoney(usdResult.value, 'USD');
  assert.ok(formatted.includes('$'));
  assert.ok(formatted.includes('.'));
});

test('convert large amount EUR to USD', () => {
  const result = convert(1000000, 'USD');
  assert.equal(result.ok, true);
  // 1000000 EUR cents = 10000 EUR
  // 10000 EUR * 1.085 USD/EUR = 10850 USD = 1085000 USD cents
  assert.equal(result.value, 1085000);
});

test('convert large amount EUR to GBP', () => {
  const result = convert(1000000, 'GBP');
